texts.2fa637939bc294da0101658339285be54c7601bb:
"""API-surface guard for AppWorld calls.

This middleware prevents the most common AppWorld failure mode: the agent
invents a top-level `apis.<service>` name before inspecting `apis`. It keeps a
small deterministic registry of top-level API names parsed from the output of
`print(dir(apis))` calls. If the agent tries to use an unobserved top-level
service, the call is skipped and the model is told to orient first.

The guard is deliberately narrow:
  * it only blocks direct `apis.<name>` attribute access, not `apis` itself,
    `dir(apis)`, `help(apis)`, `getattr(apis, ...)`, or variables;
  * once `print(dir(apis))` has been observed but its output could not be
    parsed, the guard switches to permissive mode instead of blocking forever.
"""

from __future__ import annotations

import ast
import json
import re
from typing import Any

_STATE_KEY = "api_guard"
_MARKER = "[api_guard]"
_MAX_SHOWN = 40


# ---------------------------------------------------------------------------
# AST helpers
# ---------------------------------------------------------------------------


def _dotted_path(node: ast.AST) -> str:
    """Return a dotted path string for simple Name/Attribute chains."""
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        base = _dotted_path(node.value)
        return f"{base}.{node.attr}" if base else node.attr
    return ""


def _dir_targets(code: str) -> list[str]:
    """Return paths passed to `dir(...)` in source order."""
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return []
    targets: list[str] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        if isinstance(func, ast.Name) and func.id == "dir" and len(node.args) == 1:
            path = _dotted_path(node.args[0])
            if path == "apis" or path.startswith("apis."):
                targets.append(path)
    return targets


def _direct_apis_attrs(code: str) -> set[str]:
    """Return top-level attribute names accessed directly on `apis`."""
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return set()
    attrs: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Attribute):
            if isinstance(node.value, ast.Name) and node.value.id == "apis":
                attrs.add(node.attr)
    return attrs


# ---------------------------------------------------------------------------
# Output parsing
# ---------------------------------------------------------------------------


def _looks_like_shell_result(result: str) -> bool:
    """True only for real AppWorld shell replies, not middleware skip text."""
    if not result:
        return False
    if "OUTPUT:" in result or re.search(r"^TASK_COMPLETED\s*:", result, re.M):
        return True
    try:
        data = json.loads(result)
        return isinstance(data, dict) and "task_completed" in data
    except Exception:
        return False


def _extract_output(result: str) -> str:
    """Return the shell stdout block emitted by appworld_execute."""
    if not result:
        return ""
    match = re.search(r"^OUTPUT:\n(.*?)(?=^TASK_COMPLETED\s*:|\Z)", result, re.S | re.M)
    if not match:
        # Raw fallback: the original compact JSON had an `output` field.
        return result
    return match.group(1)


def _string_lists(text: str) -> list[set[str]]:
    """Extract Python lists of string identifiers from printed output."""
    if not text:
        return []
    lists: list[set[str]] = []
    for match in re.finditer(r"\[[^\[\]]*\]", text):
        segment = match.group(0)
        try:
            value = ast.literal_eval(segment)
        except Exception:
            continue
        if not isinstance(value, list):
            continue
        members: set[str] = set()
        for item in value:
            if isinstance(item, str) and item.isidentifier():
                members.add(item)
        lists.append(members)
    return lists


def _state(ctx: Any) -> dict:
    state = getattr(ctx, "state", None)
    if state is None:
        return {}
    return state.setdefault(_STATE_KEY, {})


# ---------------------------------------------------------------------------
# Hooks
# ---------------------------------------------------------------------------


async def after_tool(name: str, args: dict, result: str, ctx) -> str:
    """Learn the top-level API surface from `dir(apis...)` output."""
    if name != "appworld_execute":
        return result

    result_text = result or ""
    if not _looks_like_shell_result(result_text):
        return result_text

    code = (args or {}).get("code", "")
    if not isinstance(code, str) or not code.strip():
        return result_text

    targets = _dir_targets(code)
    if not targets:
        return result_text

    state = _state(ctx)
    state.setdefault("orientation_seen", False)
    state["orientation_seen"] = True
    observed = state.setdefault("observed", {})

    output = _extract_output(result_text)
    lists = _string_lists(output)

    # Match `dir(...)` calls to the list representations they printed. Most
    # snippets print exactly one dir() result; when the number of printed lists
    # is ambiguous we leave the observed member set unknown (permissive) rather
    # than risk learning a wrong API inventory.
    if len(targets) == 1:
        path = targets[0]
        if len(lists) == 1:
            observed[path] = lists[0]
        else:
            observed.setdefault(path, None)
    elif len(lists) == len(targets):
        for path, members in zip(targets, lists):
            observed[path] = members
    else:
        for path in targets:
            observed.setdefault(path, None)

    return result_text


async def before_tool(name: str, args: dict, ctx) -> dict | None:
    """Block direct `apis.<unknown>` calls until orientation has happened."""
    if name != "appworld_execute":
        return None

    code = (args or {}).get("code", "")
    if not isinstance(code, str) or not code.strip():
        return None

    attrs = _direct_apis_attrs(code)
    if not attrs:
        return None

    state = _state(ctx)
    if not state:
        # No state means this middleware has not seen any appworld call yet.
        return _block(
            "Before calling `apis.<name>`, inspect the API surface first. "
            "Run exactly:\nprint(dir(apis))\n"
            "Then use only names printed in OUTPUT."
        )

    if not state.get("orientation_seen"):
        return _block(
            "Before calling `apis.<name>`, inspect the API surface first. "
            "Run exactly:\nprint(dir(apis))\n"
            "Then use only names printed in OUTPUT."
        )

    observed = state.get("observed") or {}
    apis_members = observed.get("apis")
    if apis_members is None:
        # Orientation happened but we could not parse the member list.
        # Permissive mode: do not risk blocking valid work forever.
        return None

    unknown = sorted(attr for attr in attrs if attr not in apis_members)
    if not unknown:
        return None

    known = sorted(apis_members)
    known_text = ", ".join(known[:_MAX_SHOWN])
    if len(known) > _MAX_SHOWN:
        known_text += ", ..."
    return _block(
        "Blocked `apis." + "`, `apis.".join(unknown) + "` because "
        "I have not observed that top-level API in `print(dir(apis))` output. "
        "Use only observed top-level names. "
        f"Observed top-level APIs ({len(known)}): {known_text}"
    )


def _block(message: str) -> dict:
    return {"action": "skip", "result": f"{_MARKER} {message}"}

texts.2fac0a5c213880605d421e5403a7b689b00a50f0:
"""Deterministic working-memory middleware for AppWorld.

AppWorld tasks are long, multi-step, and full of exact API names and parameter
names. The main model already sees each tool result once, but nothing keeps
the discovered API surface in front of it as a compact, always-updated board.
This middleware builds that board deterministically from observed tool results
and injects only the *new* items before the next LLM turn.

It is intentionally non-authoritative:
  * it never blocks or redirects any call;
  * it only records things it can parse deterministically from `print(dir(...))`
    output and from `apis.api_docs` output printed by the autodoc middleware;
  * it injects deltas, so the model gets a short `[memory update]` only when a
    genuinely new API/method/signature has been observed;
  * it keeps the injected text compact and machine-checkable.

The goal is to reduce hallucinated app/method/argument names in later turns and
to stop the model from re-deriving signatures it already printed earlier.
"""

from __future__ import annotations

import ast
import re
from typing import Any

_STATE_KEY = "memory"
_MARKER = "[memory update]"
_MAX_DESC = 140
_MAX_PARAMS = 14

_OUTPUT_RE = re.compile(
    r"^OUTPUT:\n(.*?)(?=^TASK_COMPLETED\s*:|\Z)", re.S | re.M
)
_HEADER_RE = re.compile(r"^\s*##\s*([^|\n]+?)\s*\|\s*([^|\n]+?)\s*$", re.M)
_PARAM_RE = re.compile(
    r"^\s*-\s*([^|\n]+?)\s*\|\s*([^|\n]*?)\s*\|\s*required=\s*(True|False)\s*\|?\s*(.*)$"
)


# ---------------------------------------------------------------------------
# Parsing helpers
# ---------------------------------------------------------------------------


def _dotted_path(node: ast.AST) -> str:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        base = _dotted_path(node.value)
        return f"{base}.{node.attr}" if base else node.attr
    return ""


def _printed_dir_targets(code: str) -> list[str]:
    """Paths passed to `print(dir(...))` calls, in source order."""
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return []
    targets: list[str] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        if not (isinstance(node.func, ast.Name) and node.func.id == "print"):
            continue
        for arg in node.args:
            if (
                isinstance(arg, ast.Call)
                and isinstance(arg.func, ast.Name)
                and arg.func.id == "dir"
                and len(arg.args) == 1
            ):
                path = _dotted_path(arg.args[0])
                if path == "apis" or path.startswith("apis."):
                    targets.append(path)
    return targets


def _extract_output(result: str) -> str:
    if not result:
        return ""
    match = _OUTPUT_RE.search(result)
    if not match:
        return result
    return match.group(1)


def _string_lists(text: str) -> list[set[str]]:
    """Return sets of identifiers for each flat Python list printed."""
    if not text:
        return []
    lists: list[set[str]] = []
    for match in re.finditer(r"\[[^\[\]]*\]", text):
        segment = match.group(0)
        try:
            value = ast.literal_eval(segment)
        except Exception:
            continue
        if not isinstance(value, list):
            continue
        members = {str(item) for item in value if isinstance(item, str) and str(item).isidentifier()}
        lists.append(members)
    return lists


def _app_from_target(path: str) -> str | None:
    if not path.startswith("apis."):
        return None
    parts = path.split(".")
    if len(parts) == 2 and parts[1].isidentifier():
        return parts[1]
    return None


def _parse_dir_results(code: str, output: str, state: dict) -> None:
    """Learn top-level and per-app dir inventories from a dir-printing call."""
    targets = _printed_dir_targets(code)
    if not targets:
        return
    lists = _string_lists(output)
    if not lists:
        return

    matches: list[tuple[str, set[str]]] = []
    if len(targets) == 1 and len(lists) == 1:
        matches.append((targets[0], lists[0]))
    elif len(lists) == len(targets):
        matches.extend(zip(targets, lists))
    else:
        return

    for path, members in matches:
        if not members:
            continue
        if path == "apis":
            top = state.setdefault("top_apis", set())
            before = len(top)
            top.update(members)
            if len(top) != before:
                state["dirty"] = True
            continue

        app = _app_from_target(path)
        if not app:
            continue
        apps = state.setdefault("app_dirs", {})
        app_members = apps.setdefault(app, set())
        before = len(app_members)
        app_members.update(members)
        if len(app_members) != before:
            state["dirty"] = True


def _parse_api_docs(output: str, state: dict) -> None:
    """Learn API signatures from printed api_docs search results."""
    if "##" not in output:
        return
    docs = state.setdefault("app_docs", {})

    current: dict | None = None
    current_app: str | None = None
    current_api: str | None = None
    pending_lines: list[str] = []

    def flush() -> None:
        nonlocal current, current_app, current_api, pending_lines
        if current is None or current_app is None or current_api is None:
            current = current_app = current_api = None
            pending_lines = []
            return
        key = f"{current_app}.{current_api}"
        old = docs.get(current_app, {}).get(current_api, {})
        desc = ""
        params: list[dict] = []
        for line in pending_lines:
            if line.strip() in {"", "---"}:
                continue
            pm = _PARAM_RE.match(line)
            if pm:
                name = pm.group(1).strip()
                ptype = pm.group(2).strip()
                required = pm.group(3).strip() == "True"
                if name:
                    params.append({"name": name, "type": ptype, "required": required})
                continue
            if not desc:
                desc = line.strip()
        new = {"params": params, "desc": desc[: _MAX_DESC]}
        old_sig = _signature(old)
        new_sig = _signature(new)
        if old_sig != new_sig:
            docs.setdefault(current_app, {})[current_api] = new
            state["dirty"] = True
        current = current_app = current_api = None
        pending_lines = []

    for line in output.splitlines():
        m = _HEADER_RE.match(line)
        if m:
            flush()
            current = {}
            current_app = m.group(1).strip()
            current_api = m.group(2).strip()
            pending_lines = []
        elif current is not None:
            pending_lines.append(line)
    flush()


def _signature(api: dict) -> str:
    if not api:
        return ""
    params = api.get("params") or []
    names = [p.get("name", "") for p in params if p.get("name")]
    return ", ".join(names)


# ---------------------------------------------------------------------------
# State
# ---------------------------------------------------------------------------


def _state(ctx: Any) -> dict:
    state = getattr(ctx, "state", None)
    if state is None:
        return {}
    bucket = state.setdefault(_STATE_KEY, {})
    bucket.setdefault("top_apis", set())
    bucket.setdefault("app_dirs", {})
    bucket.setdefault("app_docs", {})
    bucket.setdefault("dirty", False)
    bucket.setdefault("last_injected", {"top_apis": set(), "app_dirs": {}, "app_docs": {}})
    return bucket


# ---------------------------------------------------------------------------
# Hooks
# ---------------------------------------------------------------------------


async def after_tool(name: str, args: dict, result: str, ctx):
    """Record observed API surface from every AppWorld result."""
    if name != "appworld_execute":
        return result

    result_text = result or ""
    if "OUTPUT:" not in result_text:
        return result_text

    code = (args or {}).get("code", "")
    if not isinstance(code, str) or not code.strip():
        return result_text

    state = _state(ctx)
    output = _extract_output(result_text)
    _parse_dir_results(code, output, state)
    _parse_api_docs(output, state)
    return result_text


async def before_llm(messages: list, ctx):
    """Inject only the newly observed API surface as a compact user note."""
    state = _state(ctx)
    if not state or not state.get("dirty"):
        return messages

    new_parts: list[str] = []
    last = state["last_injected"]

    # Top-level apis.
    new_top = sorted(set(state.get("top_apis", set())) - set(last.get("top_apis", set())))
    if new_top:
        new_parts.append("new top-level apis: " + ", ".join(new_top))

    # Per-app dir members.
    app_dirs = state.get("app_dirs", {})
    last_app_dirs = last.get("app_dirs", {})
    for app in sorted(app_dirs):
        current = app_dirs.get(app, set())
        previous = last_app_dirs.get(app, set())
        added = sorted(current - previous)
        if added:
            shown = added[: _MAX_PARAMS]
            suffix = ", ..." if len(added) > _MAX_PARAMS else ""
            new_parts.append(f"apis.{app} members: " + ", ".join(shown) + suffix)

    # API docs (app.api(param, ...)).
    app_docs = state.get("app_docs", {})
    last_docs = last.get("app_docs", {})
    doc_lines: list[str] = []
    for app in sorted(app_docs):
        for api in sorted(app_docs[app]):
            key = f"{app}.{api}"
            info = app_docs[app][api]
            sig = _signature(info)
            old_sig = _signature(last_docs.get(app, {}).get(api, {}))
            if key in last_docs.get(app, {}) and sig == old_sig:
                continue
            params = info.get("params") or []
            parts: list[str] = []
            for p in params[:_MAX_PARAMS]:
                pname = p.get("name", "")
                ptype = p.get("type", "")
                if ptype:
                    parts.append(f"{pname}: {ptype}")
                else:
                    parts.append(pname)
            if len(params) > _MAX_PARAMS:
                parts.append("...")
            line = f"apis.{key}(" + ", ".join(parts) + ")"
            desc = (info.get("desc") or "").strip()
            if desc:
                line += f" -- {desc}"
            doc_lines.append(line)
    if doc_lines:
        new_parts.append("exact API signatures:\n" + "\n".join("- " + line for line in doc_lines))

    if not new_parts:
        state["dirty"] = False
        return messages

    note = _MARKER + "\n" + "\n".join(new_parts)
    messages = list(messages) if isinstance(messages, list) else list(messages)
    messages.append({"role": "user", "content": note})

    # Update the last-injected snapshot so we only send each fact once.
    last["top_apis"] = set(state.get("top_apis", set()))
    last["app_dirs"] = {app: set(members) for app, members in app_dirs.items()}
    last["app_docs"] = {
        app: {api: {"params": list(info.get("params", [])), "desc": info.get("desc", "")}
              for api, info in apis.items()}
        for app, apis in app_docs.items()
    }
    state["dirty"] = False
    return messages

