texts.3777e0ad89c0f7630f1410502b6d183aa83486c3:
"""Automatic API-documentation retrieval for AppWorld.

After the main agent orients with `print(dir(apis))`, this middleware asks a
small side LLM for one to three short queries that are likely to cover the
APIs needed by the task. It then injects a single read-only `appworld_execute`
call in the same turn. That call prints the AppWorld app descriptions and the
most relevant API docs (app, API name, description, and parameter list) using
the official `apis.api_docs` search API.

This is intentionally narrow:
  * it only fires once, immediately after top-level orientation;
  * it only fires when the orientation output actually contains `api_docs`;
  * it only uses the read-only `api_docs` app, never a task-side-effecting API;
  * it caps the number of search queries and printed parameters;
  * search failures are caught and printed so a bad query cannot create a
    new traceback or a new autodebug injection.
"""

from __future__ import annotations

import ast
import json
import re
from typing import Any

_STATE_KEY = "autodoc"
_MAX_QUERIES = 3
_PAGE_LIMIT = 5

_TOP_LEVEL_DIR_RE = re.compile(r"\bdir\(\s*apis\s*\)")
_TASK_COMPLETED_LINE_RE = re.compile(r"(?im)^\s*TASK_COMPLETED\s*:")
_OUTPUT_RE = re.compile(
    r"^OUTPUT:\n(.*?)(?=^TASK_COMPLETED\s*:|\Z)", re.S | re.M
)


def _extract_json(text: str) -> dict | None:
    if not text:
        return None
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.M)
    match = re.search(r"\{.*\}", cleaned, re.DOTALL)
    if not match:
        return None
    try:
        value = json.loads(match.group(0))
    except Exception:
        return None
    return value if isinstance(value, dict) else None


def _looks_like_shell_result(result: str) -> bool:
    if not result:
        return False
    if "OUTPUT:" in result or _TASK_COMPLETED_LINE_RE.search(result):
        return True
    try:
        data = json.loads(result)
        return isinstance(data, dict) and "task_completed" in data
    except Exception:
        return False


def _extract_output(result: str) -> str:
    if not result:
        return ""
    match = _OUTPUT_RE.search(result)
    if not match:
        return result
    return match.group(1)


def _string_lists(text: str) -> list[set[str]]:
    """Extract Python lists of string identifiers from printed output."""
    if not text:
        return []
    lists: list[set[str]] = []
    for match in re.finditer(r"\[[^\[\]]*\]", text):
        segment = match.group(0)
        try:
            value = ast.literal_eval(segment)
        except Exception:
            continue
        if not isinstance(value, list):
            continue
        members: set[str] = set()
        for item in value:
            if isinstance(item, str) and item.isidentifier():
                members.add(item)
        lists.append(members)
    return lists


def _state(ctx: Any) -> dict:
    state = getattr(ctx, "state", None)
    if state is None:
        return {}
    return state.setdefault(_STATE_KEY, {})


def _build_code(queries: list[str]) -> str:
    """Return a read-only snippet that prints compact, relevant API docs."""
    lines: list[str] = [
        "print('APP_DESCRIPTIONS')",
        "print(apis.api_docs.show_app_descriptions())",
    ]

    for query in queries:
        lines.append("print('\\nSEARCH_QUERY:', " + json.dumps(query) + ")")
        lines.append("_query = " + json.dumps(query))
        lines.append("try:")
        lines.append(
            "    _docs = apis.api_docs.search_api_docs("
            "query=_query, page_index=0, page_limit=%d)" % _PAGE_LIMIT
        )
        lines.append("    for _doc in _docs:")
        lines.append(
            "        print('\\n##', _doc.get('app_name'), '|', _doc.get('api_name'))"
        )
        lines.append("        print(_doc.get('description'))")
        lines.append("        for _param in (_doc.get('parameters') or []):")
        lines.append(
            "            print('  -', _param.get('name'), '|', _param.get('type'), "
            "'| required=', _param.get('required'), '|', _param.get('description'))"
        )
        lines.append("        print('---')")
        lines.append("except Exception as _exc:")
        lines.append("    print('API_DOC_SEARCH_ERROR:', type(_exc).__name__, _exc)")

    return "\n".join(lines)


async def after_tool(name: str, args: dict, result: str, ctx):
    """Queue one API-doc lookup after the first `print(dir(apis))`."""
    if name != "appworld_execute":
        return result
    if getattr(ctx, "_in_injected_call", False):
        return result
    if getattr(ctx, "_pending_injections", None):
        return result

    code = (args or {}).get("code", "")
    if not isinstance(code, str) or not _TOP_LEVEL_DIR_RE.search(code):
        return result

    result_text = result or ""
    if not _looks_like_shell_result(result_text):
        return result_text

    state = _state(ctx)
    if state.get("done"):
        return result_text

    # Only fire when we can see `api_docs` in the actual orientation output.
    # This avoids wasting an interaction when `dir(apis)` was only mentioned
    # in a comment/string or its output could not be parsed.
    output = _extract_output(result_text)
    parsed_lists = _string_lists(output)
    has_api_docs = any("api_docs" in members for members in parsed_lists)
    if not has_api_docs:
        return result_text

    available = sorted({member for members in parsed_lists for member in members})
    available_text = ", ".join(available) if available else "the apps from dir(apis)"
    question = getattr(ctx, "question", "") or ""
    prompt = (
        "You are selecting API documentation search queries for an AppWorld "
        "task. The top-level `apis` apps visible in the last output are: "
        f"{available_text}. Based on the task below, propose one to three "
        "short search queries for `apis.api_docs.search_api_docs` that are "
        "most likely to retrieve the exact APIs needed to complete the task. "
        "Use action-oriented terms (for example: 'send email', 'create "
        "playlist', 'pay request', 'file directory'). Do not invent specific "
        "API names; just provide good search strings.\n\n"
        f"TASK:\n{question}\n\n"
        'Return exactly one JSON object with a `queries` array of strings, '
        'for example:\n{"queries": ["send email", "gmail search threads"]}'
    )

    verdict = await ctx.side_text(prompt, purpose="autodoc", max_tokens=300)
    data = _extract_json(verdict or "")

    queries: list[str] = []
    if data:
        raw = data.get("queries", data.get("query", []))
        if isinstance(raw, str):
            raw = [raw]
        if isinstance(raw, list):
            queries = [
                str(q).strip()
                for q in raw
                if isinstance(q, str) and q.strip()
            ][:_MAX_QUERIES]

    state["done"] = True
    new_code = _build_code(queries)
    return {
        "result": result_text,
        "inject": [{"name": "appworld_execute", "args": {"code": new_code}}],
    }

texts.4306cc5e8991bacd9e43642764726c5e7f95b4c3:
"""Argument-binding repair for AppWorld method calls.

The remaining failures after top-level and method-level API documentation are
often calls with hallucinated parameter names or omitted required arguments.
`param_guard`-style blocking is risky because it can stall a valid call or
misread an optional signature. This middleware is deliberately *reactive*
instead: it only acts after Python has already raised an argument-binding
`TypeError`, which means the function body never ran, so re-running the call
with corrected arguments cannot duplicate a side effect.

It learns exact method signatures from the `apis.api_docs` output printed by
autodoc/method_docs (`## app | api` headers and `- name | type | required=...`
parameter lines). When a later direct `apis.<app>.<method>(...)` call fails with
a repairable binding error, a side LLM proposes a corrected snippet. The snippet
is accepted only if it is syntactically valid, still contains exactly the same
direct `apis.<app>.<method>` call as the original, uses only documented keyword
parameter names, supplies every documented required parameter, and adds no
extra `apis.*` call or `getattr(apis, ...)`. Invalid or ambiguous repairs are
left alone so the normal autodebug diagnostic path can run.
"""

from __future__ import annotations

import ast
import json
import re
from typing import Any

_STATE_KEY = "arg_repair"
_MAX_REPAIRS = 3
_MAX_CODE_CHARS = 2000
_MAX_RESULT_CHARS = 2600

_TRACEBACK_RE = re.compile(r"Traceback\s*\(most recent call last\):", re.I)
# These Python errors are raised during argument binding, before the function
# body executes. Repairing them is safe with respect to side effects.
_BINDING_ERROR_RE = re.compile(
    r"got an unexpected keyword argument"
    r"|missing\s+\d+\s+required\s+(?:positional|keyword-only)\s+argument"
    r"|takes\s+(?:\d+\s+positional arguments?\s+but\s+\d+\s+(?:were|was)\s+given"
    r"|from\s+\d+\s+to\s+\d+\s+positional arguments?\s+but\s+\d+\s+(?:were|was)\s+given)"
    r"|got multiple values for (?:keyword\s+)?argument",
    re.I,
)
_ERROR_FUNC_RE = re.compile(r"TypeError:\s*([A-Za-z_]\w*)\s*\(", re.I)

_OUTPUT_RE = re.compile(
    r"^OUTPUT:\n(.*?)(?=^TASK_COMPLETED\s*:|\Z)", re.S | re.M
)
_DOC_HEADER_RE = re.compile(r"^##\s+(.*?)\s*\|\s*(.*?)\s*$")
_PARAM_RE = re.compile(
    r"^-\s*(\w+)\s*\|\s*([^|]*?)\s*\|\s*required=\s*([Tt]rue|[Ff]alse)"
    r"(?:\s*\|\s*(.*))?$"
)


def _dotted_path(node: ast.AST) -> str:
    """Return a dotted path string for simple Name/Attribute chains."""
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        base = _dotted_path(node.value)
        return f"{base}.{node.attr}" if base else node.attr
    return ""


def _direct_api_calls(code: str) -> list[tuple[str, ast.Call]]:
    """Return (path, node) for direct `apis.<app>.<method>(...)` calls."""
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return []
    calls: list[tuple[str, ast.Call]] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        if not isinstance(node.func, ast.Attribute):
            continue
        path = _dotted_path(node.func)
        if path.startswith("apis.") and path.count(".") >= 2:
            calls.append((path, node))
    return calls


def _has_getattr_apis(tree: ast.AST) -> bool:
    """True if code dynamically accesses `apis` via getattr."""
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            if node.func.id == "getattr" and node.args:
                if _dotted_path(node.args[0]) == "apis":
                    return True
    return False


def _looks_like_shell_result(result: str) -> bool:
    """True only for real AppWorld shell replies, not middleware skip text."""
    if not result:
        return False
    if "OUTPUT:" in result or re.search(r"^TASK_COMPLETED\s*:", result, re.M):
        return True
    try:
        data = json.loads(result)
        return isinstance(data, dict) and "task_completed" in data
    except Exception:
        return False


def _extract_output(result: str) -> str:
    if not result:
        return ""
    match = _OUTPUT_RE.search(result)
    if not match:
        return result
    return match.group(1)


def _extract_json(text: str) -> dict | None:
    if not text:
        return None
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.M)
    match = re.search(r"\{.*\}", cleaned, re.DOTALL)
    if not match:
        return None
    try:
        value = json.loads(match.group(0))
    except Exception:
        return None
    return value if isinstance(value, dict) else None


def _state(ctx: Any) -> dict:
    state = getattr(ctx, "state", None)
    if state is None:
        return {}
    return state.setdefault(_STATE_KEY, {})


# ---------------------------------------------------------------------------
# Signature learning
# ---------------------------------------------------------------------------


def _learn_signatures(result: str, ctx: Any) -> None:
    """Parse API docs output printed by autodoc/method_docs into signatures."""
    if not _looks_like_shell_result(result):
        return
    output = _extract_output(result)
    if not output or "## " not in output:
        return

    state = _state(ctx)
    sigs = state.setdefault("signatures", {})
    current: tuple[str, str] | None = None
    current_desc: list[str] = []

    def save_current_desc() -> None:
        if current is None or not current_desc:
            return
        app, api = current
        entry = sigs.get(app, {}).get(api)
        if entry is not None:
            entry["desc"] = " ".join(current_desc)[:300]

    for raw_line in output.splitlines():
        line = raw_line.strip()
        header = _DOC_HEADER_RE.match(line)
        if header:
            # Flush the description belonging to the previous method before
            # switching to the new one.
            save_current_desc()
            app = header.group(1).strip()
            api = header.group(2).strip()
            if app and api:
                current = (app, api)
                current_desc = []
                app_sigs = sigs.setdefault(app, {})
                entry = app_sigs.setdefault(
                    api, {"params": [], "types": {}, "required": set(), "desc": ""}
                )
                entry.setdefault("params", [])
                entry.setdefault("types", {})
                entry.setdefault("required", set())
                entry.setdefault("desc", "")
            continue

        if current is None:
            continue

        if line.startswith("---") or not line:
            continue

        param = _PARAM_RE.match(line)
        if param:
            app, api = current
            entry = sigs[app][api]
            name = param.group(1)
            ptype = param.group(2).strip()
            required = param.group(3).lower() == "true"
            desc = (param.group(4) or "").strip()
            if name not in entry["params"]:
                entry["params"].append(name)
                entry["types"][name] = ptype
                if desc:
                    # Keep the first useful description seen for a parameter.
                    entry.setdefault("param_descs", {})
                    entry["param_descs"][name] = desc
            if required:
                entry["required"].add(name)
            continue

        # Non-parameter line following a header is part of the method description.
        current_desc.append(line)

    # Save the description of the final method seen in this result.
    save_current_desc()


# ---------------------------------------------------------------------------
# Repair
# ---------------------------------------------------------------------------


def _repairable(result: str) -> bool:
    return bool(_TRACEBACK_RE.search(result)) and bool(
        _BINDING_ERROR_RE.search(result)
    )


def _target_call(
    code: str, result: str, signatures: dict
) -> tuple[str, str, str, dict] | None:
    """Return (path, app, method, signature) if code is unambiguously repairable."""
    calls = _direct_api_calls(code)
    if len(calls) != 1:
        return None

    path, _node = calls[0]
    parts = path.split(".")
    if len(parts) != 3:
        return None
    app, method = parts[1], parts[2]
    if app in {"supervisor", "api_docs"}:
        return None

    sig = (signatures.get(app) or {}).get(method)
    if not sig:
        return None

    # The traceback must actually name the same method (when it names one).
    err = _ERROR_FUNC_RE.search(result)
    if err:
        if err.group(1) != method:
            return None
    elif method not in result:
        return None

    return path, app, method, sig


def _call_matches_signature(node: ast.Call, sig: dict) -> bool:
    """True when a direct call uses documented keywords and supplies requireds."""
    params = sig.get("params") or []

    # Repaired calls must use keyword arguments only. This removes positional-
    # order ambiguity and uses the documented parameter names directly.
    if node.args:
        return False

    supplied: set[str] = set()
    for kw in node.keywords:
        if kw.arg is None:
            # `**kwargs` cannot be checked deterministically.
            return False
        if kw.arg not in params or kw.arg in supplied:
            return False
        supplied.add(kw.arg)

    required = sig.get("required") or set()
    return required.issubset(supplied)


def _validate_repaired_code(
    new_code: str, original_code: str, path: str, sig: dict
) -> bool:
    """Accept only syntactically valid code with exactly the same, legal call."""
    if not new_code or new_code.strip() == original_code.strip():
        return False
    try:
        tree = ast.parse(new_code)
    except SyntaxError:
        return False
    if _has_getattr_apis(tree):
        return False
    calls = _direct_api_calls(new_code)
    if len(calls) != 1 or calls[0][0] != path:
        return False
    if not _call_matches_signature(calls[0][1], sig):
        return False
    if "complete_task" in new_code:
        return False
    return True


def _params_text(sig: dict) -> str:
    lines: list[str] = []
    descs = sig.get("param_descs") or {}
    for name in sig.get("params", []):
        ptype = sig.get("types", {}).get(name, "?")
        req = "required" if name in sig.get("required", set()) else "optional"
        desc = descs.get(name, "")
        lines.append(f"  - {name} | {ptype} | {req}" + (f" | {desc}" if desc else ""))
    if not lines:
        return "(no documented parameters)"
    return "\n".join(lines)


async def after_tool(name: str, args: dict, result: str, ctx):
    """Learn signatures, and on a binding TypeError queue a corrected call."""
    if name != "appworld_execute":
        return result

    result_text = result or ""
    _learn_signatures(result_text, ctx)

    if getattr(ctx, "_in_injected_call", False):
        return result
    if getattr(ctx, "_pending_injections", None):
        return result

    code = (args or {}).get("code", "")
    if not isinstance(code, str) or not code.strip():
        return result_text

    if not _repairable(result_text):
        return result_text

    state = _state(ctx)
    count = int(state.get("count", 0))
    if count >= _MAX_REPAIRS:
        return result_text

    attempted = state.setdefault("attempted", set())
    if code.strip() in attempted:
        return result_text

    signatures = state.get("signatures") or {}
    target = _target_call(code, result_text, signatures)
    if target is None:
        return result_text

    # Mark the attempt before calling the side LLM so repeated failures cannot
    # burn the side-LLM budget on the same unrecoverable snippet.
    state["count"] = count + 1
    attempted.add(code.strip())

    path, app, method, sig = target
    prompt = (
        "You are repairing a Python call in a persistent AppWorld environment. "
        "The code below raised an argument-binding TypeError, so the function "
        "body did NOT execute. Correct the arguments of the failing call only.\n\n"
        f"TASK:\n{getattr(ctx, 'question', '')}\n\n"
        f"DOCUMENTED SIGNATURE for `apis.{app}.{method}`:\n"
        f"{sig.get('desc', '')}\n"
        f"{_params_text(sig)}\n\n"
        f"FAILED CODE:\n{code[:_MAX_CODE_CHARS]}\n\n"
        f"TRACEBACK:\n{result_text[:_MAX_RESULT_CHARS]}\n\n"
        "Return exactly one JSON object with a `code` string key containing the "
        "corrected Python snippet.\n"
        "Constraints:\n"
        f"- Keep the exact same `apis.{app}.{method}(...)` call path.\n"
        "- Only change the arguments of that one call. Do not add or remove any "
        "other `apis.*` call.\n"
        "- Do not call `apis.supervisor` or any other method.\n"
        "- Preserve all other statements, prints, and variable names.\n"
        "- Pass every argument as a keyword argument (`name=value`), using only "
        "documented parameter names, and supply every required parameter.\n"
        "- If an unknown keyword was used, map it to the correct documented "
        "parameter name using its meaning/description; keep the value.\n"
        'For example: {"code": "apis.email.send_email(to=\'a@b.com\', subject=\'hi\', body=\'body\')"}'
    )

    verdict = await ctx.side_text(prompt, purpose="arg_repair", max_tokens=700)
    data = _extract_json(verdict or "")
    if not data:
        return result_text

    new_code = str(data.get("code", "") or "").strip()
    if not _validate_repaired_code(new_code, code, path, sig):
        return result_text

    return {
        "result": result_text,
        "inject": [{"name": "appworld_execute", "args": {"code": new_code}}],
    }

texts.54623ee544fee01ba03dadaad5ceef6a56a62cc0:
"""Documentation-backed argument guard for AppWorld calls.

The earlier guards prevent hallucinated top-level apps and teach exact method
names, but the model can still write a call whose keyword argument names do not
match the API documentation. This middleware closes that gap precisely:

  * it learns method signatures from the `apis.api_docs` output that autodoc
    and method_docs already print (`## app | api` followed by
    `  - name | type | required= True | description` lines);
  * before executing any direct `apis.<app>.<method>(...)` call for which it
    has a signature, it skips the call when the call uses a keyword argument
    that is not documented, or when a documented required argument is missing;
  * it is deliberately conservative: unobserved signatures are always allowed,
    `*`/`**` unpacking is always allowed, `api_docs` and `supervisor` are never
    blocked, injected read-only calls are never blocked, and the total number
    of blocks per run is capped so a noisy parser can never deadlock a run.

This targets the remaining hallucinated-parameter failure mode without the
aggressive method-level blocking that previously hurt.
"""

from __future__ import annotations

import ast
import re
from typing import Any

_STATE_KEY = "param_guard"
_MARKER = "[param_guard]"
_MAX_BLOCKS = 12

_SKIP_APPS = {"api_docs", "supervisor"}

_OUTPUT_RE = re.compile(
    r"^OUTPUT:\n(.*?)(?=^TASK_COMPLETED\s*:|\Z)", re.S | re.M
)
_TASK_COMPLETED_LINE_RE = re.compile(r"(?im)^\s*TASK_COMPLETED\s*:")
_DOC_HEADER_RE = re.compile(r"^##\s+(?P<app>[^|]+?)\s*\|\s*(?P<api>[^|]+?)\s*$")
# `required` can be printed as True/False, and in some docs it is None for
# optional parameters. Anything other than True is treated as optional.
_PARAM_RE = re.compile(
    r"^\s*-\s+(?P<name>[^|]+?)\s*\|\s*(?P<type>[^|]+?)\s*\|\s*"
    r"required=\s*(?P<req>True|False|true|false|None|null)",
)


# ---------------------------------------------------------------------------
# AST helpers
# ---------------------------------------------------------------------------


def _dotted_path(node: ast.AST) -> str:
    """Return a dotted path string for simple Name/Attribute chains."""
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        base = _dotted_path(node.value)
        return f"{base}.{node.attr}" if base else node.attr
    return ""


def _apis_method_calls(code: str):
    """Yield `(call_node, app, method)` for direct `apis.<app>.<method>(...)`."""
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        path = _dotted_path(node.func)
        if not path.startswith("apis."):
            continue
        parts = path.split(".")
        if len(parts) == 3 and parts[1].isidentifier() and parts[2].isidentifier():
            yield node, parts[1], parts[2]


# ---------------------------------------------------------------------------
# Output parsing
# ---------------------------------------------------------------------------


def _looks_like_shell_result(result: str) -> bool:
    """True only for real AppWorld shell replies, not middleware skip text."""
    if not result:
        return False
    if "OUTPUT:" in result or _TASK_COMPLETED_LINE_RE.search(result):
        return True
    try:
        import json

        data = json.loads(result)
        return isinstance(data, dict) and "task_completed" in data
    except Exception:
        return False


def _extract_output(result: str) -> str:
    if not result:
        return ""
    match = _OUTPUT_RE.search(result)
    if not match:
        return result
    return match.group(1)


def _state(ctx: Any) -> dict:
    state = getattr(ctx, "state", None)
    if state is None:
        return {}
    return state.setdefault(_STATE_KEY, {})


def _fmt_sig(app: str, method: str, sig: dict) -> str:
    params = sig.get("params") or []
    required = sig.get("required") or set()
    parts = []
    for p in params:
        parts.append(f"{p}{'' if p in required else '=...'}")
    suffix = ""
    if sig.get("var_args"):
        suffix = ", *args"
    if sig.get("var_kw"):
        suffix += ", **kwargs"
    return f"apis.{app}.{method}(" + ", ".join(parts) + suffix + ")"


# ---------------------------------------------------------------------------
# Hooks
# ---------------------------------------------------------------------------


async def after_tool(name: str, args: dict, result: str, ctx):
    """Learn method signatures from printed `apis.api_docs` output."""
    if name != "appworld_execute":
        return result

    result_text = result or ""
    if not _looks_like_shell_result(result_text):
        return result_text

    output = _extract_output(result_text)
    if not output:
        return result_text

    state = _state(ctx)
    signatures = state.setdefault("signatures", {})

    current_key: str | None = None
    for raw_line in output.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        header = _DOC_HEADER_RE.match(line)
        if header:
            app = header.group("app").strip()
            method = header.group("api").strip()
            if (
                app.isidentifier()
                and method.isidentifier()
                and app not in _SKIP_APPS
            ):
                current_key = f"{app}.{method}"
                signatures.setdefault(
                    current_key,
                    {
                        "params": [],
                        "required": set(),
                        "var_args": False,
                        "var_kw": False,
                    },
                )
            else:
                current_key = None
            continue

        if not current_key:
            continue

        param = _PARAM_RE.match(line)
        if not param:
            continue

        name = param.group("name").strip()
        required = param.group("req").lower() == "true"
        sig = signatures[current_key]

        if name.startswith("**"):
            sig["var_kw"] = True
            continue
        if name.startswith("*"):
            sig["var_args"] = True
            continue
        if name and name not in sig["params"]:
            sig["params"].append(name)
        if required and name:
            sig["required"].add(name)

    return result_text


async def before_tool(name: str, args: dict, ctx):
    """Skip calls whose documented signature is clearly violated."""
    if name != "appworld_execute":
        return None
    if getattr(ctx, "_in_injected_call", False):
        return None

    code = (args or {}).get("code", "")
    if not isinstance(code, str) or not code.strip():
        return None

    state = _state(ctx)
    signatures = state.get("signatures") or {}
    if not signatures:
        return None

    for call_node, app, method in _apis_method_calls(code):
        if app in _SKIP_APPS:
            continue

        sig = signatures.get(f"{app}.{method}")
        if not sig or not (sig.get("params") or sig.get("var_kw") or sig.get("var_args")):
            continue

        params = sig.get("params") or []
        required = sig.get("required") or set()

        # If the call uses `**payload`, we cannot inspect its keys. Allow it.
        if any(kw.arg is None for kw in call_node.keywords):
            continue

        kw_names = [kw.arg for kw in call_node.keywords if kw.arg]
        has_starred_args = any(isinstance(a, ast.Starred) for a in call_node.args)

        # 1) Unknown keyword argument names are almost always wrong when the
        #    signature is known and does not accept **kwargs. This remains safe
        #    even with `*args` because keyword names are still explicit.
        if not sig.get("var_kw") and params:
            unknown = [k for k in kw_names if k not in params]
            if unknown:
                return _block(
                    ctx,
                    state,
                    "Blocked `apis." + app + "." + method + "(...)` because "
                    "I have observed its documented signature but you used "
                    "unknown keyword argument(s): " + ", ".join(unknown) + ". "
                    "Use only documented parameter names. "
                    "Documented signature: " + _fmt_sig(app, method, sig),
                )

        # 2) Missing required arguments are deterministically wrong when the
        #    signature is known and no *args/**kwargs are declared. `*items`
        #    unpacking hides positional arguments, so skip this check for it.
        if (
            not has_starred_args
            and not sig.get("var_args")
            and not sig.get("var_kw")
        ):
            positional_names = params[: len(call_node.args)] if call_node.args else []
            provided = set(positional_names) | set(kw_names)
            missing = [p for p in params if p in required and p not in provided]
            if missing:
                return _block(
                    ctx,
                    state,
                    "Blocked `apis." + app + "." + method + "(...)` because "
                    "required parameter(s) were not provided: "
                    + ", ".join(missing) + ". "
                    "Documented signature: " + _fmt_sig(app, method, sig),
                )

    return None


def _block(ctx: Any, state: dict, message: str) -> dict | None:
    count = int(state.get("blocks", 0))
    if count >= _MAX_BLOCKS:
        return None
    state["blocks"] = count + 1
    return {"action": "skip", "result": f"{_MARKER} {message}"}

texts.56e4f97898ecb147299c11d4e23f63776aacd84b:
"""Final-answer gate for AppWorld tasks.

Keeps the agent from stopping on an incomplete or unsupported answer. It
remembers the full text of recent AppWorld tool results in `ctx.state`, uses a
cheap heuristic on the shell's own `TASK_COMPLETED` line, and enforces that the
most recent completion signal is `true` before the answer can be accepted. When
that requirement is met, it optionally asks a small side-LLM verifier to either
accept the answer or send the main agent back for one more evidence-gathering
turn.
"""

from __future__ import annotations

import json
import re

_MAX_RESULTS = 6
_MAX_HISTORY_IN_PROMPT = 4
_CODE_PREVIEW_CHARS = 600
_RESULT_PREVIEW_CHARS = 1200

_STATE_KEY = "verify_final"

# Matches the line this workspace's appworld_execute tool actually prints
# (e.g. `TASK_COMPLETED: true`). Anchoring avoids confusing a `task_completed`
# value printed inside stdout with the shell's own completion flag.
_TASK_COMPLETED_LINE_RE = re.compile(
    r"(?im)^\s*TASK_COMPLETED\s*:\s*[\"']?(true|false)[\"']?\s*$"
)


def _extract_json(text: str) -> dict | None:
    """Pull the first JSON object out of a side-LLM reply, if any."""
    if not text:
        return None
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.M)
    match = re.search(r"\{.*\}", cleaned, re.DOTALL)
    if not match:
        return None
    try:
        value = json.loads(match.group(0))
    except Exception:
        return None
    return value if isinstance(value, dict) else None


async def after_tool(name, args, result, ctx):
    """Remember full AppWorld results so the final gate can inspect them."""
    if name != "appworld_execute":
        return result

    state = getattr(ctx, "state", None)
    if state is None:
        return result
    bucket = state.setdefault(_STATE_KEY, {})
    results = bucket.setdefault("results", [])
    results.append({"args": args or {}, "result": result or ""})
    if len(results) > _MAX_RESULTS:
        results = results[-_MAX_RESULTS:]
        bucket["results"] = results
    return result


def _stored_results(ctx) -> list:
    state = getattr(ctx, "state", None)
    if not state:
        return []
    bucket = state.get(_STATE_KEY) or {}
    return bucket.get("results") or []


def _history_text(ctx) -> str:
    """Summarize recent AppWorld activity for the verifier."""
    stored = _stored_results(ctx)
    if stored:
        recent = stored[-_MAX_HISTORY_IN_PROMPT:]
        parts: list[str] = []
        for i, item in enumerate(recent, 1):
            parts.append(f"Call {i}: appworld_execute")
            code = (item.get("args") or {}).get("code", "")
            if isinstance(code, str) and code.strip():
                parts.append("Code: " + code[:_CODE_PREVIEW_CHARS].replace("\n", "\\n"))
            result = item.get("result", "") or ""
            if result:
                parts.append("Result: " + result[:_RESULT_PREVIEW_CHARS])
        return "\n\n".join(parts)

    records = getattr(ctx, "tool_history", []) or []
    recent = records[-_MAX_HISTORY_IN_PROMPT:]
    if not recent:
        return "(no tool calls yet)"

    parts = []
    for i, rec in enumerate(recent, 1):
        name = getattr(rec, "requested_name", "?")
        parts.append(f"Call {i}: {name}")
        args = getattr(rec, "requested_args", {}) or {}
        if name == "appworld_execute":
            code = args.get("code", "")
            if isinstance(code, str) and code.strip():
                parts.append("Code: " + code[:_CODE_PREVIEW_CHARS].replace("\n", "\\n"))
        preview = getattr(rec, "result_preview", "") or ""
        if preview:
            parts.append("Result: " + preview[:_RESULT_PREVIEW_CHARS])
    return "\n\n".join(parts)


def _result_completed_value(result: str) -> bool | None:
    """Return the shell's completion flag as a bool, or None if not present."""
    if not result:
        return None

    # Prefer the exact `TASK_COMPLETED: <bool>` line emitted by our tool.
    matches = _TASK_COMPLETED_LINE_RE.findall(result)
    if matches:
        return matches[-1].lower() == "true"

    # Fallback for raw/compact shell JSON that was not reformatted.
    if re.search(r"task_completed[\"']?\s*:\s*[\"']?true", result, re.I):
        return True
    if re.search(r"task_completed[\"']?\s*:\s*[\"']?false", result, re.I):
        return False
    return None


def _latest_completion(ctx) -> bool | None:
    """Return the most recent explicit completion signal, if any."""
    stored = _stored_results(ctx)
    if stored:
        for item in reversed(stored):
            completed = _result_completed_value(item.get("result", "") or "")
            if completed is not None:
                return completed
        return None

    records = getattr(ctx, "tool_history", []) or []
    for rec in reversed(records):
        if getattr(rec, "requested_name", "") != "appworld_execute":
            continue
        completed = _result_completed_value(getattr(rec, "result_preview", "") or "")
        if completed is not None:
            return completed
    return None


def _task_completed_false(ctx) -> bool:
    """Heuristic: the most recent AppWorld result explicitly says not done."""
    return _latest_completion(ctx) is False


def _task_completed_true(ctx) -> bool:
    """True only when the most recent AppWorld result explicitly says done."""
    return _latest_completion(ctx) is True


async def before_final(answer: str, ctx):
    """Return accept/continue after checking whether the answer is ready."""
    answer = (answer or "").strip()
    if not answer:
        return {"action": "accept"}

    if _task_completed_false(ctx):
        return {
            "action": "continue",
            "feedback": (
                "The AppWorld environment reports TASK_COMPLETED=false. "
                "Do not finalize yet. If you have already performed all of the "
                "requested actions, mark the task complete by calling "
                "`apis.supervisor.complete_task()` (with `answer=` only if the "
                "task asks for a value), then wait for a result whose "
                "TASK_COMPLETED line is true. Otherwise continue working: "
                "inspect the relevant APIs/state, print the exact values needed "
                "by the question, and try again."
            ),
        }

    if not _task_completed_true(ctx):
        return {
            "action": "continue",
            "feedback": (
                "I do not see a recent AppWorld tool result with "
                "TASK_COMPLETED=true, so the task is not provably finished. "
                "Do not finalize yet. Call `apis.supervisor.complete_task()` "
                "(with `answer=<exact value>` only if the task asks for a "
                "value), then wait for a tool result whose TASK_COMPLETED line "
                "is true. If the last action was not the final action, keep "
                "working and verify the exact values before marking complete."
            ),
        }

    history = _history_text(ctx)
    prompt = (
        "You are a strict verifier for an AppWorld task agent. Decide whether "
        "the proposed final answer is ready to submit.\n\n"
        f"QUESTION:\n{getattr(ctx, 'question', '')}\n\n"
        f"PROPOSED FINAL ANSWER:\n{answer}\n\n"
        f"RECENT TOOL ACTIVITY:\n{history}\n\n"
        "Return a single JSON object with keys `action` and `feedback`.\n"
        "- action=\"accept\" if the answer directly and fully answers the "
        "question, is consistent with the observed tool outputs, and has no "
        "obvious missing required detail.\n"
        "- action=\"continue\" if the answer is incomplete, vague, unsupported, "
        "or likely wrong. In `feedback`, give one short, specific instruction "
        "telling the agent exactly what to print/verify next.\n"
        "Only choose continue for a concrete missing detail or inconsistency; "
        "do not demand perfection. If the answer is already adequate, accept it."
    )

    verdict = await ctx.side_text(prompt, purpose="verify_final", max_tokens=300)
    data = _extract_json(verdict or "")
    if not data:
        return {"action": "accept"}

    action = str(data.get("action", "accept")).lower()
    feedback = str(data.get("feedback", "") or "").strip()
    if action == "continue" and feedback:
        return {"action": "continue", "feedback": feedback}
    return {"action": "accept"}

