texts.7f774591f90dc026a1a1e9f689d1774a87373bed:
"""API-surface guard for AppWorld calls.

This middleware prevents the most common AppWorld failure modes around
invented API names:

  * the agent invents a top-level `apis.<service>` name before inspecting
    `apis` -- blocked until `print(dir(apis))` has been observed and parsed;
  * after inspecting an app with `dir(apis.<app>)`, the agent invents a
    method/attribute name that was not listed -- blocked once that app's
    `dir()` output has been observed and parsed.

The guard is deliberately narrow:
  * it only blocks direct `apis.<name>` / `apis.<app>.<name>` attribute
    access, not `apis` itself, `dir(apis)`, `help(apis)`, `getattr`, or
    variables;
  * method-level blocking only applies to apps whose `dir(apis.<app>)`
    output has already been parsed; otherwise the guard stays permissive so
    it can never deadlock;
  * `apis.supervisor.complete_task` is never blocked (the final-answer
    gate handles completion separately);
  * once `print(dir(apis))` has been observed but its output could not be
    parsed, the guard switches to permissive mode instead of blocking forever.
"""

from __future__ import annotations

import ast
import json
import re
from typing import Any

_STATE_KEY = "api_guard"
_MARKER = "[api_guard]"
_MAX_SHOWN = 40


# ---------------------------------------------------------------------------
# AST helpers
# ---------------------------------------------------------------------------


def _dotted_path(node: ast.AST) -> str:
    """Return a dotted path string for simple Name/Attribute chains."""
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        base = _dotted_path(node.value)
        return f"{base}.{node.attr}" if base else node.attr
    return ""


def _dir_targets(code: str) -> list[str]:
    """Return paths passed to `dir(...)` in source order."""
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return []
    targets: list[str] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        if isinstance(func, ast.Name) and func.id == "dir" and len(node.args) == 1:
            path = _dotted_path(node.args[0])
            if path == "apis" or path.startswith("apis."):
                targets.append(path)
    return targets


def _direct_apis_attrs(code: str) -> set[str]:
    """Return top-level attribute names accessed directly on `apis`."""
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return set()
    attrs: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Attribute):
            if isinstance(node.value, ast.Name) and node.value.id == "apis":
                attrs.add(node.attr)
    return attrs


def _direct_apis_method_paths(code: str) -> set[str]:
    """Return `apis.<app>.<member>...` chains accessed directly on `apis`."""
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return set()
    paths: set[str] = set()
    for node in ast.walk(tree):
        if not isinstance(node, ast.Attribute):
            continue
        path = _dotted_path(node)
        if path.startswith("apis.") and path.count(".") >= 2:
            paths.add(path)
    return paths


# ---------------------------------------------------------------------------
# Output parsing
# ---------------------------------------------------------------------------


def _looks_like_shell_result(result: str) -> bool:
    """True only for real AppWorld shell replies, not middleware skip text."""
    if not result:
        return False
    if "OUTPUT:" in result or re.search(r"^TASK_COMPLETED\s*:", result, re.M):
        return True
    try:
        data = json.loads(result)
        return isinstance(data, dict) and "task_completed" in data
    except Exception:
        return False


def _extract_output(result: str) -> str:
    """Return the shell stdout block emitted by appworld_execute."""
    if not result:
        return ""
    match = re.search(r"^OUTPUT:\n(.*?)(?=^TASK_COMPLETED\s*:|\Z)", result, re.S | re.M)
    if not match:
        # Raw fallback: the original compact JSON had an `output` field.
        return result
    return match.group(1)


def _string_lists(text: str) -> list[set[str]]:
    """Extract Python lists of string identifiers from printed output."""
    if not text:
        return []
    lists: list[set[str]] = []
    for match in re.finditer(r"\[[^\[\]]*\]", text):
        segment = match.group(0)
        try:
            value = ast.literal_eval(segment)
        except Exception:
            continue
        if not isinstance(value, list):
            continue
        members: set[str] = set()
        for item in value:
            if isinstance(item, str) and item.isidentifier():
                members.add(item)
        lists.append(members)
    return lists


def _state(ctx: Any) -> dict:
    state = getattr(ctx, "state", None)
    if state is None:
        return {}
    return state.setdefault(_STATE_KEY, {})


# ---------------------------------------------------------------------------
# Hooks
# ---------------------------------------------------------------------------


async def after_tool(name: str, args: dict, result: str, ctx) -> str:
    """Learn the API surface from `dir(apis...)` output."""
    if name != "appworld_execute":
        return result

    result_text = result or ""
    if not _looks_like_shell_result(result_text):
        return result_text

    code = (args or {}).get("code", "")
    if not isinstance(code, str) or not code.strip():
        return result_text

    targets = _dir_targets(code)
    if not targets:
        return result_text

    state = _state(ctx)
    state.setdefault("orientation_seen", False)
    state["orientation_seen"] = True
    observed = state.setdefault("observed", {})

    output = _extract_output(result_text)
    lists = _string_lists(output)

    # Match `dir(...)` calls to the list representations they printed. Most
    # snippets print exactly one dir() result; when the number of printed lists
    # is ambiguous we leave the observed member set unknown (permissive) rather
    # than risk learning a wrong API inventory.
    if len(targets) == 1:
        path = targets[0]
        if len(lists) == 1:
            observed[path] = lists[0]
        else:
            observed.setdefault(path, None)
    elif len(lists) == len(targets):
        for path, members in zip(targets, lists):
            observed[path] = members
    else:
        for path in targets:
            observed.setdefault(path, None)

    return result_text


async def before_tool(name: str, args: dict, ctx) -> dict | None:
    """Block direct `apis.<unknown>` / `apis.<app>.<unknown>` calls."""
    if name != "appworld_execute":
        return None

    code = (args or {}).get("code", "")
    if not isinstance(code, str) or not code.strip():
        return None

    # ── Top-level service names ──────────────────────────────────────────
    attrs = _direct_apis_attrs(code)
    if attrs:
        state = _state(ctx)
        if not state or not state.get("orientation_seen"):
            return _block(
                "Before calling `apis.<name>`, inspect the API surface first. "
                "Run exactly:\nprint(dir(apis))\n"
                "Then use only names printed in OUTPUT."
            )

        observed = state.get("observed") or {}
        apis_members = observed.get("apis")
        if apis_members is not None:
            unknown = sorted(attr for attr in attrs if attr not in apis_members)
            if unknown:
                known = sorted(apis_members)
                known_text = ", ".join(known[:_MAX_SHOWN])
                if len(known) > _MAX_SHOWN:
                    known_text += ", ..."
                return _block(
                    "Blocked `apis." + "`, `apis.".join(unknown) + "` because "
                    "I have not observed that top-level API in `print(dir(apis))` "
                    "output. Use only observed top-level names. "
                    f"Observed top-level APIs ({len(known)}): {known_text}"
                )

    # ── Method/attribute names inside an already-inspected app ───────────
    method_paths = _direct_apis_method_paths(code)
    if method_paths and not getattr(ctx, "_in_injected_call", False):
        state = _state(ctx)
        observed = state.get("observed") or {}
        apis_members = observed.get("apis")

        # Only enforce method-level checks after the app itself has been
        # inspected with `dir(apis.<app>)`. Before that we stay permissive so
        # the model can discover the surface on its own.
        if apis_members is not None:
            blocked_path: str | None = None
            blocked_app: str | None = None
            observed_members: set[str] | None = None

            for path in sorted(method_paths):
                parts = path.split(".")
                if len(parts) < 3:
                    continue
                app, member = parts[1], parts[2]
                if app == "supervisor" and member == "complete_task":
                    # The supervisor completion call is handled by the
                    # final-answer gate; never block it here.
                    continue
                if app not in apis_members:
                    continue

                app_members = observed.get(f"apis.{app}")
                if app_members is None:
                    # `dir(apis.<app>)` was not parsed yet -> permissive.
                    continue
                if member in app_members:
                    continue

                blocked_path = path
                blocked_app = app
                observed_members = app_members
                break

            if blocked_path is not None and blocked_app is not None:
                known = sorted(observed_members or [])
                known_text = ", ".join(known[:_MAX_SHOWN])
                if len(known) > _MAX_SHOWN:
                    known_text += ", ..."
                return _block(
                    f"Blocked `{blocked_path}` because `{blocked_app}` was "
                    f"inspected with `dir(apis.{blocked_app})` and that "
                    "method/attribute was not listed. Use only observed "
                    f"`apis.{blocked_app}` members ({len(known)}): {known_text}"
                )

    return None


def _block(message: str) -> dict:
    return {"action": "skip", "result": f"{_MARKER} {message}"}

texts.8fc0a492f25e2622665f9e825d7fef9023fc4942:
"""Immediate duplicate-failure guard for AppWorld tool calls.

When the main agent repeats the exact same `appworld_execute` snippet that just
raised a traceback, it usually means it did not absorb the diagnostic output and
is about to burn a turn (and possibly repeat a side-effecting call). This
middleware remembers the most recent failed snippet and skips an immediate exact
repeat before execution, returning a short instruction to inspect and change the
snippet.

The guard is deliberately narrow and recoverable:
  * it only matches exact code strings (after stripping), never "similar" code;
  * it only remembers a snippet when its shell result contained a Python
    traceback;
  * any subsequent successful shell result clears the guard, so a valid retry
    after a state change is never permanently blocked;
  * injected runtime diagnostics are never blocked or used to update the guard.
"""

from __future__ import annotations

import re
from typing import Any

_STATE_KEY = "repeat_guard"
_TRACEBACK_RE = re.compile(r"Traceback\s*\(most recent call last\):", re.I)
_TASK_COMPLETED_LINE_RE = re.compile(r"(?im)^\s*TASK_COMPLETED\s*:")


def _state(ctx: Any) -> dict:
    state = getattr(ctx, "state", None)
    if state is None:
        return {}
    return state.setdefault(_STATE_KEY, {})


def _looks_like_shell_result(result: str) -> bool:
    if not result:
        return False
    if "OUTPUT:" in result or _TASK_COMPLETED_LINE_RE.search(result):
        return True
    return False


async def after_tool(name: str, args: dict, result: str, ctx):
    """Track the most recent main-model snippet that raised a traceback."""
    if name != "appworld_execute":
        return result

    if getattr(ctx, "_in_injected_call", False):
        return result

    code = (args or {}).get("code", "")
    if not isinstance(code, str) or not code.strip():
        return result

    result_text = result or ""
    code = code.strip()
    state = _state(ctx)

    if _TRACEBACK_RE.search(result_text):
        state["last_failed_code"] = code
    elif _looks_like_shell_result(result_text):
        # A real shell result without a traceback means the environment has
        # moved on; allow the same code again if it becomes necessary.
        state["last_failed_code"] = None

    return result_text


async def before_tool(name: str, args: dict, ctx) -> dict | None:
    """Skip an immediate exact repeat of the last traceback-failing snippet."""
    if name != "appworld_execute":
        return None
    if getattr(ctx, "_in_injected_call", False):
        return None

    code = (args or {}).get("code", "")
    if not isinstance(code, str) or not code.strip():
        return None

    state = _state(ctx)
    last_failed = state.get("last_failed_code")
    if not last_failed or code.strip() != last_failed:
        return None

    return {
        "action": "skip",
        "result": (
            "[repeat_guard] This exact code just raised a traceback. "
            "Do not repeat it. Read the latest diagnostic/error output, then "
            "inspect the failing object (print(dir(...)), print(type(...)), or "
            "apis.api_docs) and run corrected code."
        ),
    }

texts.97f23e8901a04f1d0e616c5ecb233f90bec136e7:
"""Deterministic final-answer pinning for AppWorld tasks.

The strongest evidence of the correct final answer is the exact value the agent
submitted to `apis.supervisor.complete_task(answer=...)`: if the shell then
reports `TASK_COMPLETED: true`, that submitted value was accepted by the task
supervisor. This middleware records that value and, at final-answer time,
replaces the model's free-text answer with the exact submitted value.

When `answer=` is not a literal but a side-effect-free expression (a variable,
attribute, subscript, f-string, or simple operator expression), the middleware
injects one read-only capture call in the same turn: `print(repr(<expr>))`.
The captured value is parsed from that injected tool result and used as the
final answer instead of the model's paraphrase.

This is intentionally conservative:
  * it only replaces the answer after the latest shell result explicitly says
    `TASK_COMPLETED: true`;
  * it never fabricates a value: if the submitted value was not a literal and
    could not be captured, the original answer is left for the final verifier;
  * capture snippets are generated deterministically, never by an LLM, and are
    limited to expressions with no calls/comprehensions/lambdas;
  * skipped tool calls (middleware guard text) are never treated as evidence
    of a submitted `complete_task` answer.
"""

from __future__ import annotations

import ast
import json
import re
from typing import Any

_STATE_KEY = "supervisor_answer"
_CAPTURE_START = "__SUPERVISOR_ANSWER_CAPTURE_START__"
_CAPTURE_END = "__SUPERVISOR_ANSWER_CAPTURE_END__"
_CAPTURE_ERROR = "__SUPERVISOR_ANSWER_CAPTURE_ERROR__"
_MAX_CAPTURES = 3

_TASK_COMPLETED_LINE_RE = re.compile(
    r"(?im)^\s*TASK_COMPLETED\s*:\s*[\"']?(true|false)[\"']?\s*$"
)
_OUTPUT_RE = re.compile(
    r"^OUTPUT:\n(.*?)(?=^TASK_COMPLETED\s*:|\Z)", re.S | re.M
)

# AST nodes that could perform side effects or evaluate arbitrary code. A
# capture expression must not contain any of these.
_FORBIDDEN_CAPTURE_NODES = (
    ast.Call,
    ast.Await,
    ast.Lambda,
    ast.ListComp,
    ast.SetComp,
    ast.DictComp,
    ast.GeneratorExp,
    ast.NamedExpr,
    ast.Yield,
    ast.YieldFrom,
)


def _state(ctx: Any) -> dict:
    state = getattr(ctx, "state", None)
    if state is None:
        return {}
    return state.setdefault(_STATE_KEY, {})


def _looks_like_shell_result(result: str) -> bool:
    """True only for real AppWorld shell replies, not middleware skip text."""
    if not result:
        return False
    if "OUTPUT:" in result or _TASK_COMPLETED_LINE_RE.search(result):
        return True
    try:
        data = json.loads(result)
        return isinstance(data, dict) and "task_completed" in data
    except Exception:
        return False


def _extract_output(result: str) -> str:
    if not result:
        return ""
    match = _OUTPUT_RE.search(result)
    if not match:
        return result
    return match.group(1)


def _result_completed(result: str) -> bool | None:
    """Return the shell's TASK_COMPLETED flag as a bool, or None if absent."""
    if not result:
        return None
    matches = _TASK_COMPLETED_LINE_RE.findall(result)
    if matches:
        return matches[-1].lower() == "true"
    return None


def _canonical(value: Any) -> str | None:
    """Convert a submitted/captured Python value to the final answer string."""
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        # Match the shell's own lowercase boolean formatting.
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return str(value)
    # None or other types mean "no safe scalar answer"; keep the original.
    return None


def _complete_task_calls(code: str) -> list[ast.Call]:
    """Return all complete_task(...) calls in source order."""
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return []
    calls: list[ast.Call] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        if isinstance(func, ast.Attribute) and func.attr == "complete_task":
            calls.append(node)
        elif isinstance(func, ast.Name) and func.id == "complete_task":
            calls.append(node)
    calls.sort(key=lambda c: (getattr(c, "lineno", 0), getattr(c, "col_offset", 0)))
    return calls


def _answer_node(call: ast.Call) -> ast.AST | None:
    """Return the AST node passed as `answer=` (or first positional arg)."""
    for kw in call.keywords:
        if kw.arg == "answer":
            return kw.value
    if call.args:
        return call.args[0]
    return None


def _safe_capture_expr(node: ast.AST) -> bool:
    """True for side-effect-free expressions we can safely re-print."""
    if isinstance(node, ast.Constant):
        # Literals are handled directly before we ever get here.
        return False
    for sub in ast.walk(node):
        if isinstance(sub, _FORBIDDEN_CAPTURE_NODES):
            return False
    return True


def _capture_code(expr: str) -> str:
    """Read-only snippet that prints repr(expr) between marker lines."""
    return "\n".join(
        [
            "print(" + json.dumps(_CAPTURE_START) + ")",
            "try:",
            "    print(repr(" + expr + "))",
            "except Exception as _exc:",
            "    print(" + json.dumps(_CAPTURE_ERROR) + ", type(_exc).__name__, _exc)",
            "print(" + json.dumps(_CAPTURE_END) + ")",
        ]
    )


def _store_captured_value(result: str, state: dict) -> None:
    """Parse the marker-delimited value from our own capture snippet."""
    output = _extract_output(result)
    if not output:
        return

    if _CAPTURE_ERROR in output:
        state["capture_error"] = True
        return

    start = output.find(_CAPTURE_START)
    end = output.find(_CAPTURE_END)
    if start == -1 or end == -1 or end <= start:
        return
    raw = output[start + len(_CAPTURE_START) : end].strip()
    if not raw:
        return

    try:
        value = ast.literal_eval(raw)
    except Exception:
        state["capture_error"] = True
        return

    canonical = _canonical(value)
    if canonical is not None:
        state["resolved_answer"] = canonical


async def after_tool(name: str, args: dict, result: str, ctx):
    """Record complete_task answers and capture non-literal submitted values."""
    if name != "appworld_execute":
        return result

    result_text = result or ""
    code = (args or {}).get("code", "")
    state = _state(ctx)

    if not _looks_like_shell_result(result_text):
        # Middleware skip messages and other non-shell text were not executed
        # in AppWorld, so they carry no submitted-answer evidence.
        return result_text

    completed = _result_completed(result_text)
    if completed is not None:
        state["last_completed"] = completed

    # Our own capture snippet: store its observed value and never re-inject.
    if isinstance(code, str) and _CAPTURE_START in code:
        _store_captured_value(result_text, state)
        return result_text

    if getattr(ctx, "_in_injected_call", False):
        return result_text

    if not isinstance(code, str) or not code.strip():
        return result_text

    calls = _complete_task_calls(code)
    if not calls:
        return result_text

    call = calls[-1]
    answer_node = _answer_node(call)

    # A new complete_task submission supersedes any previous captured value.
    state.pop("resolved_answer", None)
    state.pop("capture_error", None)

    if answer_node is None:
        state["last_call"] = {"kind": "none"}
        return result_text

    if isinstance(answer_node, ast.Constant):
        canonical = _canonical(answer_node.value)
        state["last_call"] = {"kind": "literal", "answer": canonical}
        return result_text

    if not _safe_capture_expr(answer_node):
        state["last_call"] = {"kind": "unsafe"}
        return result_text

    expr = ast.unparse(answer_node)
    state["last_call"] = {"kind": "expr", "expr": expr}

    # Inject a read-only capture so the exact submitted value is observed.
    if (
        not getattr(ctx, "_pending_injections", None)
        and int(state.get("capture_count", 0)) < _MAX_CAPTURES
    ):
        state["capture_count"] = int(state.get("capture_count", 0)) + 1
        return {
            "result": result_text,
            "inject": [
                {"name": "appworld_execute", "args": {"code": _capture_code(expr)}}
            ],
        }

    return result_text


async def before_final(answer: str, ctx):
    """Replace free-text final answers with the exact submitted value."""
    state = _state(ctx)
    if state.get("last_completed") is not True:
        return None

    resolved = state.get("resolved_answer")
    if isinstance(resolved, str) and resolved != "":
        return {"action": "replace", "answer": resolved}

    last_call = state.get("last_call") or {}
    if last_call.get("kind") == "literal":
        submitted = last_call.get("answer")
        if isinstance(submitted, str) and submitted != "":
            return {"action": "replace", "answer": submitted}

    return None

texts.9a803b25b3921e5ee1374acb9d45257af0e21f47:
"""MiniAgent workspace tool: execute code in the official AppWorld shell."""
import asyncio
import json


def _format_bool(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


async def call(args, ctx):
    endpoint = json.loads((ctx.working_dir / 'appworld-connection.json').read_text())['socket']
    reader, writer = await asyncio.open_unix_connection(endpoint, limit=8 * 1024 * 1024)
    try:
        writer.write((json.dumps({'operation': 'execute', 'code': args['code']}) + '\n').encode())
        await writer.drain()
        raw = (await reader.readline()).decode().strip()
    finally:
        writer.close()
        await writer.wait_closed()

    # The shell replies with one JSON object. Surface the fields the agent
    # actually needs (especially `task_completed`) instead of forcing the LLM
    # to parse compact JSON in the middle of a long trace.
    try:
        data = json.loads(raw)
    except Exception:
        return raw

    if not isinstance(data, dict):
        return raw

    lines = []
    output = data.get("output", "")
    if output:
        lines.append("OUTPUT:\n" + str(output))
    lines.append("TASK_COMPLETED: " + _format_bool(data.get("task_completed")))
    for key, value in data.items():
        if key in {"output", "task_completed"}:
            continue
        lines.append(f"{key}: {value}")
    return "\n".join(lines)

texts.a93ea437cba3dd9ca1dbaba2ea401f04bf50c6c6:
"""Final-answer gate for AppWorld tasks.

Keeps the agent from stopping on an incomplete or unsupported answer. It
remembers the full text of recent AppWorld tool results in `ctx.state`, uses a
cheap heuristic (`task_completed: false` in the most recent AppWorld result),
and when that is inconclusive asks a small side-LLM verifier to either accept
the answer or send the main agent back for one more evidence-gathering turn.
"""

from __future__ import annotations

import json
import re

_MAX_RESULTS = 6
_MAX_HISTORY_IN_PROMPT = 4
_CODE_PREVIEW_CHARS = 600
_RESULT_PREVIEW_CHARS = 1200

_STATE_KEY = "verify_final"

# Matches the line this workspace's appworld_execute tool actually prints
# (e.g. `TASK_COMPLETED: true`). Anchoring avoids confusing a `task_completed`
# value printed inside stdout with the shell's own completion flag.
_TASK_COMPLETED_LINE_RE = re.compile(
    r"(?im)^\s*TASK_COMPLETED\s*:\s*[\"']?(true|false)[\"']?\s*$"
)


def _extract_json(text: str) -> dict | None:
    """Pull the first JSON object out of a side-LLM reply, if any."""
    if not text:
        return None
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.M)
    match = re.search(r"\{.*\}", cleaned, re.DOTALL)
    if not match:
        return None
    try:
        value = json.loads(match.group(0))
    except Exception:
        return None
    return value if isinstance(value, dict) else None


async def after_tool(name, args, result, ctx):
    """Remember full AppWorld results so the final gate can inspect them."""
    if name != "appworld_execute":
        return result

    state = getattr(ctx, "state", None)
    if state is None:
        return result
    bucket = state.setdefault(_STATE_KEY, {})
    results = bucket.setdefault("results", [])
    results.append({"args": args or {}, "result": result or ""})
    if len(results) > _MAX_RESULTS:
        results = results[-_MAX_RESULTS:]
        bucket["results"] = results
    return result


def _stored_results(ctx) -> list:
    state = getattr(ctx, "state", None)
    if not state:
        return []
    bucket = state.get(_STATE_KEY) or {}
    return bucket.get("results") or []


def _history_text(ctx) -> str:
    """Summarize recent AppWorld activity for the verifier."""
    stored = _stored_results(ctx)
    if stored:
        recent = stored[-_MAX_HISTORY_IN_PROMPT:]
        parts: list[str] = []
        for i, item in enumerate(recent, 1):
            parts.append(f"Call {i}: appworld_execute")
            code = (item.get("args") or {}).get("code", "")
            if isinstance(code, str) and code.strip():
                parts.append("Code: " + code[:_CODE_PREVIEW_CHARS].replace("\n", "\\n"))
            result = item.get("result", "") or ""
            if result:
                parts.append("Result: " + result[:_RESULT_PREVIEW_CHARS])
        return "\n\n".join(parts)

    records = getattr(ctx, "tool_history", []) or []
    recent = records[-_MAX_HISTORY_IN_PROMPT:]
    if not recent:
        return "(no tool calls yet)"

    parts = []
    for i, rec in enumerate(recent, 1):
        name = getattr(rec, "requested_name", "?")
        parts.append(f"Call {i}: {name}")
        args = getattr(rec, "requested_args", {}) or {}
        if name == "appworld_execute":
            code = args.get("code", "")
            if isinstance(code, str) and code.strip():
                parts.append("Code: " + code[:_CODE_PREVIEW_CHARS].replace("\n", "\\n"))
        preview = getattr(rec, "result_preview", "") or ""
        if preview:
            parts.append("Result: " + preview[:_RESULT_PREVIEW_CHARS])
    return "\n\n".join(parts)


def _result_completed_false(result: str) -> bool | None:
    """Return True/False if `result` carries a completion signal, else None."""
    if not result:
        return None

    # Prefer the exact `TASK_COMPLETED: <bool>` line emitted by our tool.
    matches = _TASK_COMPLETED_LINE_RE.findall(result)
    if matches:
        return matches[-1].lower() == "false"

    # Fallback for raw/compact shell JSON that was not reformatted.
    if re.search(r"task_completed[\"']?\s*:\s*[\"']?false", result, re.I):
        return True
    if re.search(r"task_completed[\"']?\s*:\s*[\"']?true", result, re.I):
        return False
    return None


def _task_completed_false(ctx) -> bool:
    """Heuristic: the most recent AppWorld result explicitly says not done."""
    stored = _stored_results(ctx)
    if stored:
        for item in reversed(stored):
            completed = _result_completed_false(item.get("result", "") or "")
            if completed is not None:
                return completed
        return False

    records = getattr(ctx, "tool_history", []) or []
    for rec in reversed(records):
        if getattr(rec, "requested_name", "") != "appworld_execute":
            continue
        completed = _result_completed_false(getattr(rec, "result_preview", "") or "")
        if completed is not None:
            return completed
    return False


async def before_final(answer: str, ctx):
    """Return accept/continue after checking whether the answer is ready."""
    answer = (answer or "").strip()
    if not answer:
        return {"action": "accept"}

    if _task_completed_false(ctx):
        return {
            "action": "continue",
            "feedback": (
                "The AppWorld environment reports task_completed=false. "
                "Do not finalize yet. Continue working: inspect the relevant "
                "APIs/state, print the exact values needed by the question, and "
                "try again."
            ),
        }

    history = _history_text(ctx)
    prompt = (
        "You are a strict verifier for an AppWorld task agent. Decide whether "
        "the proposed final answer is ready to submit.\n\n"
        f"QUESTION:\n{getattr(ctx, 'question', '')}\n\n"
        f"PROPOSED FINAL ANSWER:\n{answer}\n\n"
        f"RECENT TOOL ACTIVITY:\n{history}\n\n"
        "Return a single JSON object with keys `action` and `feedback`.\n"
        "- action=\"accept\" if the answer directly and fully answers the "
        "question, is consistent with the observed tool outputs, and has no "
        "obvious missing required detail.\n"
        "- action=\"continue\" if the answer is incomplete, vague, unsupported, "
        "or likely wrong. In `feedback`, give one short, specific instruction "
        "telling the agent exactly what to print/verify next.\n"
        "Only choose continue for a concrete missing detail or inconsistency; "
        "do not demand perfection. If the answer is already adequate, accept it."
    )

    verdict = await ctx.side_text(prompt, purpose="verify_final", max_tokens=300)
    data = _extract_json(verdict or "")
    if not data:
        return {"action": "accept"}

    action = str(data.get("action", "accept")).lower()
    feedback = str(data.get("feedback", "") or "").strip()
    if action == "continue" and feedback:
        return {"action": "continue", "feedback": feedback}
    return {"action": "accept"}

texts.ab96df94e72050fa4e0bee38f485f6009410503e:
"""Final-answer gate for AppWorld tasks, with an evidence ledger and
supervisor-answer pinning.

This gate has three jobs:

1. It remembers a compact ledger of recent AppWorld tool results instead of
   only a few previews, so the verifier can still see the evidence that
   supports (or contradicts) the answer even when it scrolled out of the main
   model's immediate view.
2. It parses `apis.supervisor.complete_task(answer=...)` calls and records the
   literal answer value(s) submitted to the supervisor.
3. It hard-refuses to finalize until the most recent AppWorld result reports
   `TASK_COMPLETED: true`, then asks a side-LLM verifier to either accept the
   answer, send the agent back with one specific missing-evidence instruction,
   or accept with a tightened exact answer string (preferring observed values
   and the answer actually passed to `complete_task`).

The gate is intentionally conservative: any JSON/LLM failure falls back to
accept, and the side verifier is asked not to demand perfection.
"""

from __future__ import annotations

import ast
import json
import re

_MAX_RESULTS = 10
_MAX_HISTORY_IN_PROMPT = 6
_CODE_PREVIEW_CHARS = 800
_RESULT_PREVIEW_CHARS = 1200

_STATE_KEY = "verify_final"

# Matches the line this workspace's appworld_execute tool actually prints
# (e.g. `TASK_COMPLETED: true`). Anchoring avoids confusing a `task_completed`
# value printed inside stdout with the shell's own completion flag.
_TASK_COMPLETED_LINE_RE = re.compile(
    r"(?im)^\s*TASK_COMPLETED\s*:\s*[\"']?(true|false)[\"']?\s*$"
)


def _extract_json(text: str) -> dict | None:
    """Pull the first JSON object out of a side-LLM reply, if any."""
    if not text:
        return None
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.M)
    match = re.search(r"\{.*\}", cleaned, re.DOTALL)
    if not match:
        return None
    try:
        value = json.loads(match.group(0))
    except Exception:
        return None
    return value if isinstance(value, dict) else None


def _dotted_path(node: ast.AST) -> str:
    """Return a dotted path string for simple Name/Attribute chains."""
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        base = _dotted_path(node.value)
        return f"{base}.{node.attr}" if base else node.attr
    return ""


def _literal_value(node: ast.AST) -> str | None:
    """Return a display value for simple Python literals only."""
    if isinstance(node, ast.Constant):
        value = node.value
        if value is None:
            return "None"
        if isinstance(value, bool):
            return "True" if value else "False"
        if isinstance(value, (str, int, float)):
            return str(value)
    return None


def _extract_complete_task_answers(code: str) -> list[str]:
    """Return literal `answer=` values from `complete_task(...)` calls."""
    if not code:
        return []
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return []
    answers: list[str] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        path = _dotted_path(node.func)
        if not (path == "complete_task" or path.endswith(".complete_task")):
            continue
        answer_kw = False
        for kw in node.keywords:
            if kw.arg == "answer":
                answer_kw = True
                value = _literal_value(kw.value)
                if value is not None:
                    answers.append(value)
        if not answer_kw and node.args:
            value = _literal_value(node.args[0])
            if value is not None:
                answers.append(value)
    return answers


def _state_bucket(ctx) -> dict:
    state = getattr(ctx, "state", None)
    if state is None:
        return {}
    return state.setdefault(_STATE_KEY, {})


async def after_tool(name, args, result, ctx):
    """Remember recent AppWorld results and complete_task answers."""
    if name != "appworld_execute":
        return result

    bucket = _state_bucket(ctx)
    if bucket is None:
        return result

    code = (args or {}).get("code", "")
    results = bucket.setdefault("results", [])
    results.append({"args": args or {}, "result": result or ""})
    if len(results) > _MAX_RESULTS:
        results = results[-_MAX_RESULTS:]
        bucket["results"] = results

    if isinstance(code, str) and code.strip():
        answers = _extract_complete_task_answers(code)
        if answers:
            submitted = bucket.setdefault("submitted_answers", [])
            submitted.extend(answers)
            if len(submitted) > 4:
                submitted = submitted[-4:]
            bucket["submitted_answers"] = submitted

    return result


def _stored_results(ctx) -> list:
    bucket = _state_bucket(ctx)
    if not bucket:
        return []
    return bucket.get("results") or []


def _submitted_answers_text(ctx) -> str:
    bucket = _state_bucket(ctx)
    if not bucket:
        return "(none observed)"
    answers = bucket.get("submitted_answers") or []
    if not answers:
        return "(none observed)"
    return "; ".join(answers)


def _plan_text(ctx) -> str:
    """Return the early task plan/checklist if task_plan produced one."""
    state = getattr(ctx, "state", None)
    if not state:
        return ""
    plan_state = state.get("task_plan") or {}
    goal = str(plan_state.get("goal", "") or "").strip()
    checks = plan_state.get("checks") or []
    if not goal and not checks:
        return ""
    lines = []
    if goal:
        lines.append("Goal: " + goal)
    if checks:
        lines.append("Checks:")
        lines.extend("- " + str(c) for c in checks)
    return "\n".join(lines)


def _history_text(ctx) -> str:
    """Summarize the full recent AppWorld activity ledger for the verifier."""
    stored = _stored_results(ctx)
    if stored:
        recent = stored[-_MAX_HISTORY_IN_PROMPT:]
        parts: list[str] = []
        for i, item in enumerate(recent, 1):
            parts.append(f"Call {i}: appworld_execute")
            code = (item.get("args") or {}).get("code", "")
            if isinstance(code, str) and code.strip():
                parts.append(
                    "Code: " + code[:_CODE_PREVIEW_CHARS].replace("\n", "\\n")
                )
            result = item.get("result", "") or ""
            if result:
                parts.append(
                    "Result: " + result[:_RESULT_PREVIEW_CHARS]
                )
        return "\n\n".join(parts)

    records = getattr(ctx, "tool_history", []) or []
    recent = records[-_MAX_HISTORY_IN_PROMPT:]
    if not recent:
        return "(no tool calls yet)"

    parts = []
    for i, rec in enumerate(recent, 1):
        name = getattr(rec, "requested_name", "?")
        parts.append(f"Call {i}: {name}")
        args = getattr(rec, "requested_args", {}) or {}
        if name == "appworld_execute":
            code = args.get("code", "")
            if isinstance(code, str) and code.strip():
                parts.append(
                    "Code: " + code[:_CODE_PREVIEW_CHARS].replace("\n", "\\n")
                )
        preview = getattr(rec, "result_preview", "") or ""
        if preview:
            parts.append("Result: " + preview[:_RESULT_PREVIEW_CHARS])
    return "\n\n".join(parts)


def _result_completed_value(result: str) -> bool | None:
    """Return the shell's completion flag as a bool, or None if not present."""
    if not result:
        return None

    # Prefer the exact `TASK_COMPLETED: <bool>` line emitted by our tool.
    matches = _TASK_COMPLETED_LINE_RE.findall(result)
    if matches:
        return matches[-1].lower() == "true"

    # Fallback for raw/compact shell JSON that was not reformatted.
    if re.search(r"task_completed[\"']?\s*:\s*[\"']?true", result, re.I):
        return True
    if re.search(r"task_completed[\"']?\s*:\s*[\"']?false", result, re.I):
        return False
    return None


def _latest_completion(ctx) -> bool | None:
    """Return the most recent explicit completion signal, if any."""
    stored = _stored_results(ctx)
    if stored:
        for item in reversed(stored):
            completed = _result_completed_value(item.get("result", "") or "")
            if completed is not None:
                return completed
        return None

    records = getattr(ctx, "tool_history", []) or []
    for rec in reversed(records):
        if getattr(rec, "requested_name", "") != "appworld_execute":
            continue
        completed = _result_completed_value(getattr(rec, "result_preview", "") or "")
        if completed is not None:
            return completed
    return None


def _task_completed_false(ctx) -> bool:
    """Heuristic: the most recent AppWorld result explicitly says not done."""
    return _latest_completion(ctx) is False


def _task_completed_true(ctx) -> bool:
    """True only when the most recent AppWorld result explicitly says done."""
    return _latest_completion(ctx) is True


async def before_final(answer: str, ctx):
    """Return accept/replace/continue after checking whether the answer is ready."""
    answer = (answer or "").strip()
    if not answer:
        return {"action": "accept"}

    if _task_completed_false(ctx):
        return {
            "action": "continue",
            "feedback": (
                "The AppWorld environment reports TASK_COMPLETED=false. "
                "Do not finalize yet. If you have already performed all of the "
                "requested actions, mark the task complete by calling "
                "`apis.supervisor.complete_task()` (with `answer=` only if the "
                "task asks for a value), then wait for a result whose "
                "TASK_COMPLETED line is true. Otherwise continue working: "
                "inspect the relevant APIs/state, print the exact values needed "
                "by the question, and try again."
            ),
        }

    if not _task_completed_true(ctx):
        return {
            "action": "continue",
            "feedback": (
                "I do not see a recent AppWorld tool result with "
                "TASK_COMPLETED=true, so the task is not provably finished. "
                "Do not finalize yet. Call `apis.supervisor.complete_task()` "
                "(with `answer=<exact value>` only if the task asks for a "
                "value), then wait for a tool result whose TASK_COMPLETED line "
                "is true. If the last action was not the final action, keep "
                "working and verify the exact values before marking complete."
            ),
        }

    history = _history_text(ctx)
    plan = _plan_text(ctx)
    submitted = _submitted_answers_text(ctx)
    plan_block = f"\n\nTASK PLAN:\n{plan}" if plan else ""
    prompt = (
        "You are a strict verifier for an AppWorld task agent. Decide whether "
        "the proposed final answer is ready to submit, and if so produce the "
        "exact final answer string that should be returned.\n\n"
        f"QUESTION:\n{getattr(ctx, 'question', '')}\n\n"
        f"PROPOSED FINAL ANSWER:\n{answer}\n\n"
        f"ANSWER(S) SUBMITTED TO apis.supervisor.complete_task:\n{submitted}\n"
        f"RECENT TOOL ACTIVITY (evidence ledger):\n{history}"
        f"{plan_block}\n\n"
        "Return a single JSON object with keys `action`, `feedback`, and "
        "optionally `answer`.\n"
        "- action=\"accept\" if the answer directly and fully answers the "
        "question, is consistent with the observed tool outputs, and has no "
        "obvious missing required detail.\n"
        "- action=\"continue\" if the answer is incomplete, vague, unsupported, "
        "or likely wrong. In `feedback`, give one short, specific instruction "
        "telling the agent exactly what to print/verify next.\n"
        "If you accept, set `answer` to the exact final answer string that "
        "should be returned. Prefer a concise value that exactly matches the "
        "observed tool outputs. If an answer submitted to "
        "`apis.supervisor.complete_task` is consistent with those outputs, "
        "use that exact submitted string; if it contradicts the outputs, "
        "trust the outputs and continue. Do not add explanations or prose "
        "unless the question explicitly asks for them. If the proposed answer "
        "is already that exact string, repeat it.\n"
        "Only choose continue for a concrete missing detail or inconsistency; "
        "do not demand perfection. If the answer is already adequate, accept it."
    )

    verdict = await ctx.side_text(prompt, purpose="verify_final", max_tokens=400)
    data = _extract_json(verdict or "")
    if not data:
        return {"action": "accept"}

    action = str(data.get("action", "accept")).lower()
    feedback = str(data.get("feedback", "") or "").strip()
    if action == "continue" and feedback:
        return {"action": "continue", "feedback": feedback}

    if action == "accept":
        tightened = str(data.get("answer", "") or "").strip()
        if tightened and tightened != answer:
            return {"action": "replace", "answer": tightened}
        return {"action": "accept"}

    return {"action": "accept"}

